mapper.select:
SELECT w.* FROM user_favorite_word w
WHERE w.user_id=#{user}

  AND (w.lemma LIKE #{pattern} ESCAPE '!'
    OR EXISTS(SELECT 1 FROM favorite_word_context x WHERE x.favorite_word_id=w.id AND x.sentence_snapshot LIKE #{pattern} ESCAPE '!'))


  AND EXISTS(SELECT 1 FROM favorite_word_context x WHERE x.favorite_word_id=w.id AND x.book_title_snapshot=#{sourceTitle})


  AND (w.created_at <> #{afterAt}
  OR (w.created_at=#{afterAt} AND w.id <> #{afterId}))

ORDER BY w.created_at DESC,w.id DESC
LIMIT #{limit}
